import React, { useState } from 'react';
import { User, Briefcase, X, ShieldCheck } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  
  // Paste your image link here
  const bgUrl = "https://i.pinimg.com/1200x/f7/6c/1c/f76c1cc5bcb154fb0d4ed32d9e1f65bc.jpg";

  return (
    <div 
      className="min-h-screen bg-cover bg-center flex flex-col items-center justify-center p-6"
      style={{ backgroundImage: `linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url(${bgUrl})` }}
    >
      <div className="text-center mb-10 z-10">
        <h1 className="text-4xl font-black text-white mb-2">Join Talent Pool</h1>
        <p className="text-gray-200">Select your account type to continue</p>
      </div>
      
      {/* Selection Toggle */}
      <div className="bg-white/90 backdrop-blur-md p-2 rounded-full shadow-2xl flex w-full max-w-lg z-10">
        <button onClick={() => setShowModal('student')} className="flex-1 py-6 rounded-full hover:bg-purple-100 transition-all flex flex-col items-center">
          <User className="text-purple-600 mb-1" size={28} />
          <span className="font-bold">Student</span>
        </button>
        <button onClick={() => setShowModal('hr')} className="flex-1 py-6 rounded-full hover:bg-blue-100 transition-all flex flex-col items-center">
          <Briefcase className="text-blue-600 mb-1" size={28} />
          <span className="font-bold">HR / Company</span>
        </button>
      </div>

      {/* Simplified Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden">
            <div className={`p-4 text-white flex justify-between ${showModal === 'student' ? 'bg-purple-600' : 'bg-blue-600'}`}>
              <span className="font-bold uppercase tracking-widest">{showModal} Registration</span>
              <X className="cursor-pointer" onClick={() => setShowModal(null)} />
            </div>
            <form className="p-6 space-y-4">
              <input type="text" placeholder="Full Name" className="w-full p-3 bg-gray-50 border rounded-xl outline-none" />
              <input type="email" placeholder="Email Address" className="w-full p-3 bg-gray-50 border rounded-xl outline-none" />
              <button className="w-full py-3 bg-gray-900 text-white rounded-xl font-bold">Register Now</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Register;
